	["Removes the effects of the supports, without removing the data\nUse \"rebuild all\" to apply the effects again"] = "データを削除せずに、サポートの効果を取り除きます\n効果を再度適用するには「Rebuild All」を使用してください",
	["Reparse all the inputs incase they have been disabled or they have changed since loading the build or importing"] = "ビルドの読み込みや取込以降に無効化または変更された場合に備えて、すべての入力を再解析します",
