	["Stat"] = "ステータス",
	["Support gems:"] = "サポートジェム:",
	["The account has no characters to import."] = "このアカウントには取り込めるキャラクターがありません。",
	["This is a special group created for the enemy explosion effect,\nwhich comes from the following sources:"] = "これは敵の爆発効果のために作成された特別なグループであり、\n以下のソースに由来します:",
	["This is for party play, to export support character, it enables the exporting of auras, curses and modifiers to the enemy"] = "これはパーティプレイ用です。サポートキャラクターをエクスポートするためのもので、オーラ・呪い・敵へのモディファイアのエクスポートを有効にします",
	["This sets the import button to append to the current party lists instead of replacing them (curses will still replace)"] = "取込ボタンを、現在のパーティリストを置き換える代わりに追加するように設定します(呪いは引き続き置き換えられます)",
	["This shows the advanced info like what stats each aura/curse etc are adding, as well as enables the ability to edit them without a re-export\nDo not edit any boxes unless you know what you are doing, use copy/paste or import instead"] = "各オーラ/呪いなどが追加しているステータスといった詳細情報を表示し、再出力せずに編集できるようにします\n仕組みを理解していない限りどのボックスも編集せず、コピー/ペーストまたは取込を使用してください",
	["This socket group cannot be deleted as it is created by an equipped item."] = "このソケットグループは装備中のアイテムによって作成されているため削除できません。",
	["This will allow the skill to benefit from modifiers on the item that affect socketed gems."] = "これにより、ソケットされたジェムに影響するアイテム上のモディファイアの恩恵をスキルが受けられるようになります。",
	["To be used with totems, minions, shot-gunning of projectiles (e.g., VD, magma-orbs),"] = "トーテム、ミニオン、投射物のショットガン(例: VD、マグマオーブ)、",
	["To import a build it must be exported with \"Export support\" enabled in the import/export tab\n\tAuras with the highest effect will take priority, your curses will take priority over a support's\n\t\n\tAll of these effects can be found in the Calcs tab"] = "ビルドを取り込むには、取込/出力タブで「Export support」を有効にして出力する必要があります\n\t効果が最も高いオーラが優先され、あなたの呪いはサポートの呪いより優先されます\n\t\n\tこれらの効果はすべてCalcsタブで確認できます",
	["To import a build, enter URL or code here:"] = "ビルドを取り込むには、URLまたはコードをここに入力してください:",
	["To start importing a character, select your character's realm:"] = "キャラクターの取込を開始するには、キャラクターのレルムを選択してください:",
	["Tree set:"] = "ツリーセット:",
	["Tree:"] = "ツリー:",
	["UNIQUE"] = "ユニーク",
	["Usage Tips:\n- You can copy/paste socket groups using Ctrl+C and Ctrl+V.\n- Ctrl + Click to enable/disable socket groups.\n- Ctrl + Right click to include/exclude in FullDPS calculations.\n- Right click to set as the Main skill group.\n"] = "使い方のヒント:\n- Ctrl+CとCtrl+Vでソケットグループをコピー/ペーストできます。\n- Ctrl+クリックでソケットグループの有効/無効を切り替えます。\n- Ctrl+右クリックでFullDPS計算への含める/含めないを切り替えます。\n- 右クリックでメインスキルグループに設定します。\n",
	["Warcry Skills"] = "ウォークライスキル",
	["You can use Ctrl +/- (or Ctrl+Scroll) to zoom in and out and Ctrl+0 to reset.\nThis field also supports different colors.  Using the caret symbol (^) followed by a Hex code or a number (0-9) will set the color.\nBelow are some common color codes PoB uses:\t"] = "Ctrl +/-(またはCtrl+スクロール)で拡大・縮小、Ctrl+0でリセットできます。\nこのフィールドは複数の色にも対応しています。キャレット記号(^)に続けてHexコードまたは数字(0-9)を入力すると色を設定できます。\n以下はPoBが使用する一般的なカラーコードです:\t",
	["You cannot delete this group, but it will disappear if you lose the above sources."] = "このグループは削除できませんが、上記のソースを失うと消えます。",
	["Your Build"] = "あなたのビルド",
	["multi-hit projectiles (e.g. ball-lightning), traps, mines."] = "多段ヒットの投射物(例: ボールライトニング)、トラップ、マインに使用します。",

	-- ============================================================
	-- 設定タブ: 全設定ラベル + ホバーツールチップ (ConfigOptions.lua)
	-- ============================================================
	["\t1% increased Movement Speed per 20 Rampage"] = "\tRampage20ごとに移動速度1%増加",
	["\t1% increased character size per stack."] = "\tスタックごとにキャラクターサイズ1%増加。",
	["\t1% increased movement speed"] = "\t移動速度1%増加",
	["\t10% additional Physical Damage Reduction"] = "\t物理ダメージ軽減10%追加",
	["\t10% increased Effect of Curses"] = "\t呪いの効果10%増加",
	["\t100% increased Damage"] = "\tダメージ100%増加",
	["\t100% increased chance to be Critically Hit"] = "\tクリティカルヒットを受ける確率が100%増加",
	["\t15% Chance to Avoid all Damage from Hits"] = "\tヒットによる全ダメージを回避する確率15%",
	["\t15% increased Evasion Rating"] = "\t回避レーティング15%増加",
	["\t2% increased Damage per 20 Rampage"] = "\tRampage20ごとにダメージが2%増加",
	["\t20% increased ^x3F6DB3Cold ^7Damage taken"] = "\t受ける^x3F6DB3冷気 ^7ダメージが20%増加",
	["\t20% increased ^xB97123Fire ^7Damage taken"] = "\t被^xB97123炎^7ダメージ20%増加",
	["\t20% less Elemental Damage taken"] = "\t受ける属性ダメージが20%減少",
	["\t20% less Movement Speed"] = "\t移動速度が20%減少",
	["\t25% increased Attack, Cast and Movement Speed"] = "\tアタック、詠唱、移動速度が25%増加",
	["\t3% increased Skill Speed"] = "\tスキル速度3%増加",
	["\t30% increased Movement Speed"] = "\t移動速度が30%増加",
	["\t5% increased Attack Speed"] = "\tアタックスピード5%増加",
	["\t5% increased Cast Speed"] = "\t詠唱速度5%増加",
	["\t50% less Critical Strike Chance"] = "\tクリティカル率50%減少(less)",
	["\t50% more Elemental Damage"] = "\t属性ダメージ50%上昇",
	["\tAverage: Damage Reduction from Defending with Double Armour is proportional to chance"] = "\t平均: 二重アーマーでの防御によるダメージ軽減は確率に比例する",
	["\tAverage: Modifiers will grant one third of their value to ^xB97123Fire^7, ^x3F6DB3Cold^7, and ^xADAA47Lightning ^7simultaneously"] = "\t平均: モディファイアは値の3分の1を^xB97123炎^7、^x3F6DB3冷気^7、^xADAA47雷 ^7に同時に付与する",
	["\tAverage: The cooldown is adjusted to reflect the average time between uses, factoring in effects such as a chance to not consume a cooldown."] = "\t平均: クールダウンは使用間隔の平均時間を反映するよう調整され、クールダウンを消費しない確率などの効果が考慮される。",
	["\tAverage: damage is based on the average application"] = "\t平均: ダメージは平均的な適用に基づく",
	["\tAverage: damage is based on the average application, including both crits and non-crits"] = "\t平均: ダメージはクリティカルと非クリティカルの両方を含む平均適用に基づく",
	["\tAverage: includes burst regen, averaged based on uptime"] = "\t平均: バースト自動回復を含み、稼働率に基づいて平均化される",
	["\tAverage: includes chance gains, averaged based on uptime"] = "\t平均: 確率による獲得を含み、稼働時間に基づいて平均化される",
	["\tAverage: uses the Average of all typed damage types (except Damage Over Time and Untyped)"] = "\t平均: 型付けされた全ダメージタイプの平均を使用する(継続ダメージと型なしを除く)",
	["\tAvoidance Chance"] = "\t回避確率",
	["\tBase: The cooldown is calculated with normal behavior."] = "\tBase: クールダウンは通常の挙動で計算される。",
	["\tBlock/Spell Block Chance"] = "\tブロック/スペルブロック確率",
	["\tBurst: includes full burst regen"] = "\tバースト: 完全なバースト自動回復を含む",
	["\tCrits Only: damage is based solely on Ailments inflicted with crits"] = "\tクリティカルのみ: ダメージはクリティカルで与えた状態異常のみに基づく",
	["\tDiluting Touch: 9% reduced Flask charges gained and 9% reduced Flask Effect per stack"] = "\tDiluting Touch: スタックごとにフラスコチャージ獲得量9%減少、フラスコ効果9%減少",
	["\tDodge/Spell Dodge Chance"] = "\tドッジ/スペルドッジ確率",
	["\tEach Magic enemy grants 2 Power"] = "\tマジック敵ごとに2パワーを付与する",
	["\tEach Normal enemy grants 1 Power"] = "\tNormalの敵ごとにパワーを1付与する",
	["\tEach Rare enemy grants 10 Power"] = "\tレア敵1体ごとにパワー10を付与",
	["\tEach Unique enemy grants 20 Power"] = "\tユニーク敵1体ごとに20パワーを付与する",
	["\tEnemies take 50% more Attack Damage"] = "\t敵は受けるアタックダメージが50%増加(more)",
	["\tEroding Touch: 6% inc Damage Taken per stack"] = "\tEroding Touch: スタックごとに被ダメージ6%増加",
	["\tMax Effect: always ignores if you have any chance"] = "\t最大効果: 少しでも確率があれば常に無視する",
	["\tMax Effect: damage is based on maximum effect"] = "\t最大効果: ダメージは最大効果に基づく",
	["\tMaximum: always Defend with Double Armour"] = "\t最大: 常に2倍のアーマーで防御する",
	["\tMaximum: treats all chances as certain"] = "\t最大: すべての確率を確定として扱う",
	["\tMinimum: does not include burst regen"] = "\t最小: バースト自動回復を含まない",
	["\tMinimum: does not include chances"] = "\t最小: チャンスを含めない",
	["\tMinimum: never Defend with Double Armour"] = "\t最小: Double Armourで防御しない",
	["\tMinimum: never ignores unless chance is at least 100%"] = "\t最小: 確率が100%以上でない限り無視しない",
	["\tMost monsters and the players' character are this size."] = "\tほとんどのモンスターとプレイヤーキャラクターはこのサイズ。",
	["\tParalysing Touch: 6% reduced Action Speed per stack"] = "\tParalysing Touch: スタックごとにアクション速度6%減少",
	["\tSpell Suppression Chance"] = "\tスペル軽減チャンス",
	["\tThis is the size of most humanoid bosses (i.e. The Maven; The Shaper; Izaro)"] = "\tこれはほとんどの人型ボスのサイズ (例: The Maven; The Shaper; Izaro)",
	["\tThis is the size of some larger bosses (i.e. King Kaom; Vaal Oversoul)"] = "\tこれは一部の大型ボス(King Kaom、Vaal Oversoulなど)のサイズ",
	["\tThis is the size of some of the largest bosses (i.e. Nucleus of the Maven; Tsoagoth, The Brine King)"] = "\tこれは最大級のボスの一部のサイズ (例: Nucleus of the Maven、Tsoagoth, The Brine King)",
	["\tWasting Touch: 9% reduced ^xE05030Life ^7and ^x88FFFFEnergy Shield ^7recovery rate per stack"] = "\tWasting Touch: スタックごとに^xE05030ライフ^7および^x88FFFFエナジーシールド^7の回復率が9%減少",
	["\t^xB97123Fire ^7/ ^x3F6DB3Cold ^7/ ^xADAA47Lightning^7: Modifiers will grant their full value as the specified element"] = "\t^xB97123炎 ^7/ ^x3F6DB3冷気 ^7/ ^xADAA47雷^7: 修飾効果は指定した属性として完全な値を付与する",
	[" -15% Reduced ^x33FF77Evasion"] = " ^x33FF77回避 ^7が15%減少",
