	[" Maim applies the following effects."] = " 重傷は以下の効果を適用する。",
	[" They are also Light Stunned when they become pinned."] = " 固定された際には軽い気絶も発生する。",
	[" eg at 100% the enemy deals its maximum damage"] = " 例: 100%で敵は最大ダメージを与える",
