	["Sacrifice 5% ^x88FFFFEnergy Shield^7 when you cast a Spell to give that Spell 30% more Damage."] = "スペルを詠唱するとき5%の^x88FFFFエナジーシールド^7を犠牲にし、そのスペルに30%多くのダメージを与える。",
	["Sand Stance"] = "Sand Stance",
	["Sapped ^7enemies deal less damage, up to 20%."] = "衰弱(Sap) ^7状態の敵は与えるダメージが減少する、最大20%。",
	["Scavenged Plating:"] = "Scavenged Plating:",
