	["Seconds building Stoicism:"] = "Stoicism構築の秒数:",
	["Seconds since last reset. Stoicism I: 1%/s (full 20s). Stoicism II: 2%/s (full 10s)."] = "前回のリセットからの秒数。Stoicism I: 1%/s (満タンまで20s)。Stoicism II: 2%/s (満タンまで10s)。",
	["Sets the EHP calc to not apply gain on block and suppress effects"] = "EHP計算でブロック時・軽減時の獲得効果を適用しないように設定する",
	["Sets the EHP calc to pretend its unlucky and reduce the effects of random events such as"] = "EHP計算を不運と仮定し、以下のようなランダムイベントの効果を減少させる",
	["Sets the blade count for Blade Vortex skills used by spectres."] = "スペクターが使用するBlade Vortexスキルのブレード数を設定する。",
	["Sets the maximum ^xE05030Life ^7of the Skeleton that is being targeted."] = "対象としているスケルトンの最大^xE05030ライフ^7を設定する。",
	["Sets the maximum ^xE05030life ^7of the target corpse for Detonate Dead and similar skills."] = "Detonate Deadや類似スキルの対象死体の最大^xE05030ライフ^7を設定する。",
	["Sets the number of active Spectral Wolves."] = "アクティブなSpectral Wolvesの数を設定する。",
