	["The Parry debuff grants:"] = "Parryデバフは以下を付与する:",
	["The amount of valour consumed for the placed banner"] = "設置したバナーに消費されるvalourの量",
	["The default and minimum level for pinnacle bosses and uber pinnacle bosses is 82."] = "ピナクルボスおよびウーバーピナクルボスのデフォルトおよび最小レベルは82。",
	["The default is 1.5 times the enemy's base damage, which is the same value"] = "デフォルトは敵の基礎ダメージの1.5倍で、これは同じ値",
	["The default level of normal enemies and bosses scales with player level unless manually set."] = "通常の敵とボスのデフォルトレベルは、手動で設定しない限りプレイヤーレベルに応じて変動する。",
	["The effect of Elusive decays over time."] = "回避(Elusive)の効果は時間とともに減衰する。",
	["The enemy will automatically be considered to be Cursed if you have at least one curse enabled,"] = "呪いを少なくとも1つ有効にしている場合、敵は自動的に呪い状態とみなされる。",
	["The enemy will automatically be considered to be Unique if they are a Boss."] = "敵がボスである場合、自動的にユニークとみなされる。",
	["The exact weapon is unknown but should be similar to Glass Shank"] = "正確な武器は不明だが、Glass Shankに類似すると考えられる",
	["The maximum level for normal enemies and all bosses is 85."] = "通常の敵とすべてのボスの最大レベルは85。",
