	["This also implies you have 'Consumed a corpse Recently'"] = "これは「最近死体を消費した」ことも意味する",
	["This applies -20% ^x3F6DB3Cold Resistance ^7to the enemy."] = "これは敵に^x3F6DB3冷気耐性^7-20%を適用する。",
