	["This effect will only be applied while you can inflict ^x3F6DB3Brittle."] = "この効果は^x3F6DB3脆性^7を付与できる間のみ適用される。",
	["This effect will only be applied while you can inflict ^xB97123Scorched."] = "この効果は^xB97123灼熱^7を付与できる間のみ適用される。",
