	["This locks it at the default value"] = "これをデフォルト値に固定する",
	["This multiplies the damage of a given skill in pvp, for instance any with damage multiplier specific to pvp (from skill or support or item like sire of shards)"] = "PvPにおける特定スキルのダメージを乗算する。例えばPvP専用のダメージ倍率を持つもの(スキル、サポート、またはsire of shardsのようなアイテムによる)",
	["This option enables Manastorm's ^xADAA47Lightning ^7Damage Buff."] = "このオプションはManastormの^xADAA47雷^7ダメージバフを有効にする。",
