	["This option is specific to Oni-Goroshi."] = "このオプションはOni-Goroshi専用である。",
	["This option is specific to Vulconus."] = "このオプションはVulconus専用である。",
	["This option prevents EE from being reset by the hit damage of your main skill."] = "このオプションはメインスキルのヒットダメージによってEEがリセットされるのを防ぐ。",
