	["This option sets whether an enemy is between you and your linked target."] = "このオプションは、自分とリンク対象の間に敵がいるかどうかを設定する。",
	["This option sets whether or not the enemy has hit you with ^x3F6DB3Cold Damage^7 in the last 4 seconds."] = "このオプションは、敵が直前4秒間に^x3F6DB3冷気ダメージ^7で自身をヒットしたかどうかを設定する。",
	["This option sets whether or not the enemy has hit you with ^xADAA47Lightning Damage^7 in the last 4 seconds."] = "このオプションは過去4秒間に敵があなたに^xADAA47雷ダメージ^7でヒットしたかどうかを設定する。",
	["This option sets whether or not the enemy has hit you with ^xB97123Fire Damage^7 in the last 4 seconds."] = "このオプションは、敵が直近4秒以内に^xB97123炎ダメージ^7で自分にヒットしたかどうかを設定する。",
	["This option will also allow you to input the effect of Critical Weakness."] = "このオプションでCritical Weaknessの効果も入力できる。",
	["This option will also allow you to input the effect of ^x3F6DB3Brittle."] = "このオプションでは^x3F6DB3脆性^7の効果も入力できる。",
