	["This overrides the default damage amount used to estimate your damage reduction from armour."] = "これはアーマーによるダメージ軽減を推定するために使用されるデフォルトのダメージ量を上書きする。",
	["This overrides the default enemy level used to estimate your hit, ^x33FF77evade ^7chance, and damage reduction."] = "これは自分のヒット、^x33FF77回避^7率、ダメージ軽減の推定に使用されるデフォルトの敵レベルを上書きする。",
	["This setting has no effect if you have 100% chance to Defend with Double Armour."] = "Double Armourで防御する確率が100%の場合、この設定は効果がない。",
	["This will affect all 'per Summoned Totem' modifiers, even for non-Totem skills."] = "これは非トーテムスキルであっても、すべての「召喚トーテムごと」のモディファイアに影響する。",
