	["You will automatically be considered to be on Low ^x7070FFMana ^7if you have at least 50% ^x7070FFmana ^7reserved,"] = "^x7070FFマナ ^7を50%以上確保している場合、自動的に低^x7070FFマナ ^7状態とみなされる。",
	["You will automatically be considered to be on Low ^x88FFFFEnergy Shield ^7if you have at least 50% ^x88FFFFES ^7reserved,"] = "^x88FFFFES^7を50%以上確保している場合、自動的に低^x88FFFFエナジーシールド^7状態とみなされる。",
	["You will automatically be considered to have Attacked Recently if your main skill is an attack,"] = "メインスキルがアタックの場合、自動的に最近アタックしたとみなされる。",
	["You will automatically be considered to have Cast a Spell Recently if your main skill is a spell,"] = "メインスキルがスペルの場合、最近スペルを詠唱したと自動的にみなされる、",
	["You will automatically be considered to have Hit Recently if your main skill Hits and is self-cast,"] = "メインスキルがヒットし、かつ自己詠唱である場合、自動的に最近ヒットしたとみなされる。",
	["You will automatically be considered to have Summoned a Totem Recently if your main skill is a Totem,"] = "メインスキルがトーテムの場合、最近トーテムを召喚したと自動的にみなされる、",
	["You will automatically be considered to have a Totem if your main skill is a Totem,"] = "メインスキルがトーテムの場合、自動的にトーテムを持っているとみなされる。",
	["You will automatically be considered to have used a Minion skill Recently if your main skill is a Minion skill,"] = "メインスキルがミニオンスキルの場合、自動的に最近ミニオンスキルを使用したとみなされる。",
	["You will automatically be considered to have used a Movement skill Recently if your main skill is a movement skill,"] = "メインスキルが移動スキルの場合、自動的に最近移動スキルを使用したとみなされる。",
	["You will automatically be considered to have used a Vaal skill Recently if your main skill is a Vaal skill,"] = "メインスキルがVaalスキルである場合、自動的に最近Vaalスキルを使用したとみなされる。",
	["Your Absolution Skill Damage will not be scaled with Count setting."] = "AbsolutionのスキルダメージはCount設定でスケールしない。",
	["^1Nothing^7"] = "^1なし^7",
	["^x3F6DB3Chill ^7+ ^xADAA47Shock ^7+ ^xB97123Ignite"] = "^x3F6DB3冷却 ^7+ ^xADAA47感電 ^7+ ^xB97123発火",
	["^x3F6DB3Chilling"] = "^x3F6DB3冷却",
	["^xADAA47Shocking"] = "^xADAA47感電",
	["^xB97123Igniting"] = "^xB97123発火中",
	["based on the amount of damage it has mitigated in the last second."] = "直前1秒間に軽減したダメージ量に基づく。",
	["based on the amount of damage it has mitigated."] = "軽減したダメージ量に基づく。",
	["but you can use this option to force it if necessary."] = "このオプションで必要に応じて強制できる。",
	["equal to 50% of Sacrificed ^x7070FFMana ^7for 4 seconds)"] = "犠牲にした^x7070FFマナ^7の50%に等しい、4秒間)",
	["the strongest one will apply instead unless this option would apply a stronger ^xADAA47Sap."] = "このオプションがより強い^xADAA47衰弱(Sap)^7を適用しない限り、最も強いものが代わりに適用される。",
	["the strongest one will apply instead unless this option would apply a stronger ^xADAA47Shock."] = "このオプションがより強力な^xADAA47感電^7を適用しない限り、最も強力なものが代わりに適用される。",
	["this will allow you to input the effect of the ^xADAA47Shock ^7applied to the enemy."] = "これにより敵に適用された^xADAA47感電^7の効果を入力できる。",
	["this will enable the Arcane Surge buff itself. (Grants 15% increased Cast Speed and 20% more Mana Regeneration rate)"] = "これによりアーケインサージのバフ自体が有効になる。(詠唱速度15%増加とマナ自動回復速度20%増加(more)を付与)",
	["this will enable the Elusive buff itself:"] = "これにより回避(Elusive)のバフ自体が有効になる:",
	["this will enable the Onslaught buff itself. (Grants 20% increased Attack, Cast, and Movement Speed)"] = "これにより猛攻バフ自体が有効になる。(アタック、詠唱、移動速度を20%増加)",
	["this will enable the Quicksand Hourglass buff itself."] = "これによりQuicksand Hourglassのバフ自体が有効になる。",
	["up to 40% more damage over time to the skills it supports."] = "サポート対象のスキルに最大40%の継続ダメージ増加。",
	["used in-game to calculate the estimate shown on the character sheet."] = "ゲーム内でキャラクターシートに表示される推定値の計算に使用される。",
	["will be added to the value provided in # of ^x7070FFMana ^7spent Recently."] = "最近消費した^x7070FFマナ^7の数 # に指定された値に加算される。",
	["with no penalty for targets within 2 metres and up to 90% less Accuracy for targets further than 12 metres away-"] = "2メートル以内の対象にはペナルティがなく、12メートルより離れた対象には最大90%の命中低下となる-",

	-- ============================================================
	-- UIツールチップ (各タブ Classes/*.lua の AddLine / tooltipText)
	-- ============================================================
	["  Common:"] = "  共通:",
	["- Doesn't require authorization."] = "- 認証は不要です。",
	["- Requires authorization on pathofexile.com."] = "- pathofexile.com での認証が必要です。",
	["- You can generate and perform searches for the private leagues you are participating."] = "- 参加中のプライベートリーグ向けの検索を生成・実行できます。",
	["- You can generate weighted search URLs but have to visit the trade site and manually import items."] = "- 重み付け検索URLは生成できますが、取引サイトを訪れて手動でアイテムをインポートする必要があります。",
	["- You can only generate weighted searches for public leagues. (Generated searches can be modified"] = "- 重み付け検索はパブリックリーグ向けにのみ生成できます。(生成された検索は他のリーグやレルムで動作するよう",
	["- You can search, compare, and quickly import items without leaving Path of Building."] = "- Path of Buildingから離れずにアイテムの検索・比較・素早いインポートができます。",
	["- You can select an item and search it directly."] = "- アイテムを選択して直接検索できます。",
	["- You cannot search and compare items in Path of Building."] = "- Path of Building内でアイテムの検索・比較はできません。",
	["Acceptable Range is: 1 to 10"] = "指定可能な範囲: 1〜10",
	["Activate this charm."] = "このチャームを有効化する。",
	["Activate this flask."] = "このフラスコを有効化する。",
	["Additional Effects From Quality:"] = "クオリティによる追加効果:",
	["Additional post filtering options can be done these include:"] = "追加の後処理フィルタリングオプションを利用できます。内容は次のとおりです:",
	["After selecting a row You can also shift+click on another row to select a range of rows to search."] = "行を選択した後、別の行を shift+クリックすると、検索する行の範囲を選択できる。",
	["Any manual changes made to your fallback nodes are lost when you click the generate button, as it completely replaces them."] = "フォールバックノードに加えた手動の変更は、生成ボタンをクリックすると完全に置き換えられるため失われる。",
	["Apply augments and anoints from current gear when comparing new gear, given they are possible to add to the new item."] = "新しい装備を比較する際に、新しいアイテムに追加可能であれば、現在の装備のオーグメントとアノイントを適用する。",
	["Changes the colour scheme used for the node power display on the passive tree."] = "パッシブツリーのノードパワー表示に使用するカラースキームを変更する。",
	["Changes which protocol is used when downloading updates and importing builds."] = "アップデートのダウンロードやビルドのインポート時に使用するプロトコルを変更する。",
	["Check that the item's title and base name are in the correct format."] = "アイテムのタイトルとベース名が正しい形式かを確認してください。",
	["Choose a percentage between 100% and 250% or revert to the system default."] = "100%から250%の間でパーセンテージを選択するか、システムのデフォルトに戻す。",
	["Click this button to generate new fallback node weights, replacing your old ones."] = "このボタンをクリックすると、古いものを置き換えて新しいフォールバックノードウェイトを生成する。",
	["Click to generate and copy a trade URL for searching for jewels in this list."] = "クリックすると、このリスト内のジュエルを検索するための trade URL を生成してコピーする。",
	["Contains searches from the official trading site to help find"] = "公式取引サイトからの検索を含み、このビルドに",
	["Control + click to open in web-browser"] = "Control + クリックでウェブブラウザで開きます",
	["Creates a weighted search to find the highest Stat Value items for this slot."] = "このスロットで最も高いステータス値のアイテムを見つけるためのウェイト付き検索を作成する。",
	["Currency Conversion rates are pulled from PoE Ninja"] = "通貨換算レートはPoE Ninjaから取得されます",
	["Currently Links Skills do not export"] = "現在、リンクされたスキルはエクスポートされません",
	["Currently sorting by:"] = "現在の並べ替え基準:",
	["Default scroll direction is:"] = "デフォルトのスクロール方向:",
	["Destination for Import/clear"] = "インポート/クリアの対象先",
	["Display all item affix slots as a stacked list instead of hiding them in dropdowns"] = "すべてのアイテムのアフィックススロットをドロップダウンに隠すのではなく、積み重ねたリストとして表示する",
	["Do not Autosave builds while on Dev branch"] = "Dev ブランチではビルドを自動保存しない",
	["Double click to add this jewel to your build."] = "ダブルクリックでこのジュエルをビルドに追加します。",
	["Double click to modify this stats weight multiplier."] = "ダブルクリックでこのステータスのウェイト倍率を変更する。",
	["Each page fetches up to 10 items."] = "各ページで最大10件のアイテムを取得します。",
	["Effective charm stats:"] = "実効チャームステータス:",
	["Effective flask stats:"] = "実効フラスコステータス:",
	["Enable this option to exclude nodes that you do not have allocated on your active passive skill tree."] = "このオプションを有効にすると、アクティブなパッシブスキルツリーで割り振っていないノードを除外する。",
	["Enter a valid trade URL"] = "有効な取引URLを入力してください",
	["Expected format is 0x000000. "] = "想定される形式は 0x000000。 ",
	["Experience multiplier:"] = "経験値倍率:",
	["Fallback node weights are only used when no matching entry exists in the desired nodes list, allowing you to override or disable specific automatic weights."] = "フォールバックノードウェイトは、希望ノードリストに一致するエントリが存在しない場合にのみ使用され、特定の自動ウェイトを上書きまたは無効化できる。",
	["Fallback node weights typically contain automatically generated stat weights based on your current build."] = "フォールバックノードウェイトには通常、現在のビルドに基づいて自動生成されたステータスウェイトが含まれる。",
	["For Normal and Magic items, the base name must be somewhere in the first line. E.g.:"] = "ノーマル・マジックアイテムの場合、ベース名が最初の行のどこかに含まれている必要があります。例:",
	["For Rare and Unique items, the first 2 lines must be the title and base name. E.g.:"] = "レア・ユニークアイテムの場合、最初の2行はタイトルとベース名である必要があります。例:",
	["For nodes with multiple stats this slider controls the weight of the first stat listed."] = "複数のステータスを持つノードでは、このスライダーは最初に表示されたステータスのウェイトを制御する。",
	["For nodes with multiple stats this slider controls the weight of the second stat listed."] = "複数のステータスを持つノードでは、このスライダーは2番目に表示されたステータスのウェイトを制御する。",
	["Highest Stat Value - Sort from highest to lowest Stat Value change of equipping item"] = "ステータス値が最高 - 装備時のステータス値変化が高い順に並べ替えます",
	["Highest Stat Value / Price - Sorts from highest to lowest by estimated Stat Value per currency"] = "ステータス値/価格が最高 - 通貨あたりの推定ステータス値が高い順に並べ替えます",
	["Highest Weight - Displays the order retrieved from trade"] = "最高ウェイト - tradeから取得した順序を表示する",
	["If updating while inside a build, please re-load the build after saving."] = "ビルドを開いている状態で更新する場合は、保存後にビルドを再読み込みすること。",
	["If you have additional requirements that the trade tool doesn't cover (e.g. Adorned Magic jewels),"] = "tradeツールでカバーされない追加の要件がある場合(例: Adorned Magic ジュエル)、",
	["Limit of Node distance to search (lower = faster)"] = "検索するノード距離の上限(小さいほど高速)",
	["Lowest Price - Sorts from lowest to highest price of retrieved items"] = "価格が最安 - 取得したアイテムの価格が安い順に並べ替えます",
	["No Session Mode^7"] = "セッションなしモード^7",
	["Node List:"] = "ノード一覧:",
	["Note that even if you are authenticated, you can click this button again to show the search link."] = "認証済みであっても、このボタンを再度クリックすると検索リンクを表示できる点に注意。",
	["Only show Active gems"] = "アクティブジェムのみ表示",
	["Only show Support gems"] = "サポートジェムのみ表示",
	["Overrides Windows DPI scaling inside Path of Building."] = "Path of Building 内で Windows の DPI スケーリングを上書きする。",
	["Overrides the default hex colour for highlighting nodes in passive tree search. "] = "パッシブツリー検索でノードをハイライトするためのデフォルトの16進カラーを上書きする。 ",
	["Overrides the default hex colour for negative values in breakdowns. "] = "内訳の負の値に対するデフォルトの16進カラーを上書きする。 ",
	["Overrides the default hex colour for positive values in breakdowns. "] = "内訳の正の値に対するデフォルトの16進カラーを上書きする。 ",
	["Overrides the default save location for builds."] = "ビルドのデフォルト保存場所を上書きする。",
	["Paste the URL in a web browser to search."] = "URLをWebブラウザに貼り付けて検索する。",
	["Prefix your search with \"oil:\" to search by anoint recipe."] = "検索の先頭に \"oil:\" を付けると、アノイントレシピで検索する。",
	["Protect allocated nodes during search."] = "検索中に割り振り済みのノードを保護する。",
	["Removes the effects of the supports, without removing the data"] = "データは残したまま、サポートの効果を除去します",
	["Requires PoB to restart for it to take effect"] = "反映するには PoB の再起動が必要",
	["Scroll Down = Move left"] = "下にスクロール = 左へ移動",
	["Scroll Up = Move right"] = "上にスクロール = 右へ移動",
	["Seeds that do not meet the minimum weight threshold for a desired node are excluded from the search results."] = "希望ノードの最小ウェイト閾値を満たさないシードは検索結果から除外される。",
	["Session Mode^7"] = "セッションモード^7",
	["Set the default level of your builds. If this is higher than 1, manual level mode will be enabled by default in new builds."] = "ビルドのデフォルトレベルを設定する。これが1より大きい場合、新しいビルドではデフォルトで手動レベルモードが有効になる。",
	["Set the default quality that can be overwritten by build-related quality settings in the skill panel."] = "スキルパネルのビルド関連のクオリティ設定で上書きできる、デフォルトのクオリティを設定する。",
	["Set the default quality that will be applied to newly created or pasted items."] = "新規作成または貼り付けたアイテムに適用される、デフォルトのクオリティを設定する。",
	["Show ^8(Not supported in PoB yet) ^7next to unsupported mods"] = "非対応の mod の横に ^8(Not supported in PoB yet) ^7を表示する",
	["Sorted by "] = "並べ替え基準: ",
	["Sorts the weights by the stats selected multiplied by a value"] = "選択したステータスに値を掛けてウェイトを並べ替えます",
	["Specify maximum number of item pages to retrieve per search from PoE Trade."] = "PoE Tradeの検索ごとに取得するアイテムページの最大数を指定します。",
	["Spectres:"] = "スペクター:",
	["The Trader feature supports two modes of operation depending on the authorization availability."] = "Trader機能は認証の可否に応じて2つの動作モードに対応しています。",
	["The URL is also copied to the clipboard."] = "URLもクリップボードにコピーされます。",
	["The default location is: '"] = "デフォルトの場所: '",
	["The item is invalid."] = "このアイテムは無効です。",
	["This can be useful if transforming certain notables would break your build."] = "特定のノータブルを変換するとビルドが壊れてしまう場合に役立つ。",
	["This can be useful if you're never going to path towards those excluded nodes and don't care what happens to them."] = "除外したノードへ向かってパスを通すつもりがなく、それらがどうなっても気にしない場合に役立つ。",
	["This contains a list of your desired nodes along with their primary, secondary, and minimum weights."] = "希望ノードのリストと、それぞれの一次・二次・最小ウェイトを含む。",
	["This contains a list of your fallback nodes along with their primary, secondary, and minimum weights."] = "フォールバックノードのリストと、それぞれの一次・二次・最小ウェイトを含む。",
	["This controls the maximum amount of points that need to be spent to grab a node before its filtered out"] = "ノードを取得するために消費する必要があるポイントの最大数を制御し、それを超えるノードはフィルタで除外される",
	["This list can be updated manually or by selecting the node you want to update via the search dropdown list and then moving the node weight sliders."] = "このリストは手動で更新するか、検索ドロップダウンリストで更新したいノードを選択してからノードウェイトのスライダーを動かすことで更新できる。",
	["This slider controls the weight of the following stat:"] = "このスライダーは次のステータスのウェイトを制御する:",
	["Tip: To reach this node by a different path, hold Shift, then trace the path and click this node"] = "ヒント: このノードへ別の経路で到達するには、Shiftを押しながら経路をたどってこのノードをクリックします",
	["To search for multiple terms: (increased.fire.damage|increased.area.of.effect|etc)"] = "複数の語句を検索するには: (increased.fire.damage|increased.area.of.effect|etc)",
	["Updates are limited to once per hour and not necessary more than once per day"] = "更新は1時間に1回までに制限されており、1日に1回を超える必要はありません",
	["Use \"rebuild all\" to apply the effects again"] = "効果を再度適用するには \"rebuild all\" を使用してください",
	["Uses Lua pattern matching for complex searches."] = "複雑な検索には Lua パターンマッチングを使用する。",
	["Weighted Sum searches will always sort using descending weighted sum"] = "重み付け合計検索は常に重み付け合計の降順で並べ替えられます",
	["You can click this button to authorize PoB by logging in."] = "このボタンをクリックしてログインすることでPoBを認証できます。",
	["You can click to select a row so that search begins from there."] = "行をクリックして選択すると、そこから検索を開始できる。",
	["You must log in to use the search feature"] = "検索機能を使用するにはログインが必要です",
	["on trade site to work on other leagues and realms)"] = "取引サイト上で変更できます)",
	["similar or better items for this build"] = "適した同等以上のアイテムを見つけやすくします",
	["you can add them, copy the link here, and press \"Price Item\" to evaluate the items."] = "それらを追加し、ここにリンクをコピーして \"Price Item\" を押すとアイテムを評価できる。",
}
